<section class="panel"><div class="panel-head"><div><h2>Products</h2><p>Manual, Amazon API and hybrid product records.</p></div><a class="primary-button" href="<?= e(url('admin/products/new')) ?>">+ Add product</a></div><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Source</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['display_title'] ?: $p['title']) ?></strong><small><?= e($p['brand_name'] ?? '') ?></small></td><td><?= e($p['category_name'] ?? '—') ?></td><td><span class="badge"><?= e($p['source']) ?></span></td><td><?= $p['price']!==null ? e(($p['currency'] ?? 'INR').' '.number_format((float)$p['price'],2)) : '—' ?></td><td><?= !empty($p['active'])?'Active':'Inactive' ?></td><td><a href="<?= e(url('admin/products/'.(int)$p['id'].'/edit')) ?>">Edit</a></td></tr><?php endforeach; ?><?php if(!$products): ?><tr><td colspan="6" class="empty">No products yet.</td></tr><?php endif; ?></tbody></table></section>